import re

from ..cus.section_ctrl import SectionCtrl as Ctrl
from ..section_generic import TextBasedSectionGeneric
from ..utils.logger import logger

trf_type = "udp"
trf_packet_size = "200"
trf_packet_rate = "1"
attach_rate = "1.0"
wait_time = "1000"


_section_string = """\
# WARNING: This file was auto generated, make a copy before editing as it might get overwritten
transfer ue_traffic_dl
    type {trf_type}
    packetSize {trf_packet_size}
    dir downlink
    packetRate {trf_packet_rate}

transfer ue_traffic_ul
    type {trf_type}
    packetSize {trf_packet_size}
    dir uplink
    packetRate {trf_packet_rate}

application app_ue_traffic [ DEFAULT ]
    startTransfer ue_traffic_dl on DEFAULT as ue_traffic_dl_alias
    startTransfer ue_traffic_ul on DEFAULT as ue_traffic_ul_alias
    wait {wait_time}
    stopTransfer ue_traffic_dl_alias
    stopTransfer ue_traffic_ul_alias

mobileSession ue_traffic
    connectBearer DEFAULT as DEFAULT_alias
    startApplication app_ue_traffic [ DEFAULT_alias ] as app_ue_traffic_alias &
    wait allApplicationsFinish
    releaseBearer DEFAULT_alias

testScenario
    ue_traffic
        cells [ {cells} ]
        rate {attach_rate} /s
        number {number_of_cells}
"""


class SectionScenario(TextBasedSectionGeneric):

    def __init__(self, subsection_separator=""):
        super().__init__(subsection_separator)

    def _prepare_section_content(self, ue_config, enb_config, hw_config, execution_config, *args, **kwargs):
        cus_keys = Ctrl._get_cus_keys(ue_config)
        available_sectors = []
        for i, cus_key in enumerate(cus_keys):
            cell_tab_per_cus = self.get_cell_tab_per_ctrl(cus_key, enb_config, hw_config)
            if not cell_tab_per_cus:
                logger.warning(f"Empty sector section declaration in ctrl_{str(i + 1)}. Skipping...")
                continue
            available_sectors.extend(cell_tab_per_cus)

        self._section_content.append(
            _section_string.format(
                trf_type=trf_type,
                trf_packet_size=trf_packet_size,
                trf_packet_rate=trf_packet_rate,
                wait_time=wait_time,
                attach_rate=attach_rate,
                cells=" ".join(sorted(available_sectors, key=lambda x: int(x))),
                number_of_cells=len(available_sectors),
            )
        )

    def generate_section_content(self, *args, **kwargs):
        self._prepare_section_content(*args, **kwargs)
        return self._subsection_separator.join(self._section_content)

    def get_cell_tab_per_ctrl(self, cus_key, enb_config, hw_config):
        ctrl_cus_id = re.search(r"cus(\d+)", cus_key).group(1)
        hw_map = Ctrl.get_hw_map(enb_config)
        radio_to_cus_map = Ctrl.get_radio_to_cus_map(hw_map, hw_config)
        sectors = Ctrl.get_enb_cell_id_tab_per_cus(radio_to_cus_map, enb_config, ctrl_cus_id)
        cell_id_to_cus_cell_id_map = Ctrl.get_cell_id_to_overall_cell_id_map(enb_config)

        sectors_tab_per_ctrl = []
        for enb_id, enb_cell_tab in sectors.items():
            for cell in enb_cell_tab:
                try:
                    sectors_tab_per_ctrl.append(str(cell_id_to_cus_cell_id_map[enb_id][cell]))
                except Exception:
                    pass
        return sorted(sectors_tab_per_ctrl, key=lambda x: int(x))
